def schema_drift(expected, actual):
    result = set()

    def collect_leaves(schema, prefix):
        for key, value in schema.items():
            path = f"{prefix}.{key}" if prefix else str(key)
            if isinstance(value, dict):
                collect_leaves(value, path)
            else:
                result.add(path)

    def compare(e, a, prefix):
        for key, e_value in e.items():
            path = f"{prefix}.{key}" if prefix else str(key)

            if key not in a:
                if isinstance(e_value, dict):
                    collect_leaves(e_value, path)
                else:
                    result.add(path)
            else:
                a_value = a[key]

                if isinstance(e_value, dict) and isinstance(a_value, dict):
                    compare(e_value, a_value, path)
                elif e_value != a_value:
                    result.add(path)

        for key, a_value in a.items():
            if key not in e:
                path = f"{prefix}.{key}" if prefix else str(key)

                if isinstance(a_value, dict):
                    collect_leaves(a_value, path)
                else:
                    result.add(path)

    compare(expected, actual, "")
    return sorted(result)
