def merge_payload_ranges(items):
    validated = []
    for item in items:
        start, end, payload = item
        if start > end:
            raise ValueError("start must not be greater than end")
        validated.append([start, end, payload])

    validated.sort(key=lambda x: (x[0], x[1]))

    active = []
    result = []

    for start, end, payload in validated:
        keep = []
        for interval in active:
            if interval[1] < start - 1:
                result.append(interval)
            else:
                keep.append(interval)
        active = keep

        new_start, new_end = start, end
        merged = False
        keep = []

        for interval in active:
            if interval[2] == payload:
                if interval[0] < new_start:
                    new_start = interval[0]
                if interval[1] > new_end:
                    new_end = interval[1]
                merged = True
            else:
                keep.append(interval)

        active = keep
        if merged:
            active.append([new_start, new_end, payload])
        else:
            active.append([start, end, payload])

    result.extend(active)
    result.sort(key=lambda x: (x[0], x[1]))
    return result

